// Adapter Wix Blog — siapkan header & konten Ricos dari kredensial user (API key + site id)
const IN = $input.first().json;
const X = (IN.cms || {}).wix || {};
const A = IN.article || {};
const action = IN.action === 'publish' ? 'publish' : 'draft';
const postId = String(IN.postId || '').trim();

// ===== Markdown mini-parser (dipakai adapter WordPress, Wix, Sanity, Shopify) =====
// Placeholder gambar Markimate: baris `![alt](markimate:image:N)` → html: <img data-markimate-idx=N>, portable text: {_type:'image', _markimateIdx:N} (diganti asset oleh adapter), ricos: dilewati.
// parseMarkdown(md) -> [{type:'heading',level,inlines}|{type:'paragraph',inlines}|{type:'list',ordered,items:[inlines]}|{type:'quote',inlines}]
// inlines: [{text, bold, italic, code, href}]
function parseInline(s) {
  const out = []; const src = String(s || '');
  const push = (t, m) => { if (t) out.push(Object.assign({ text: t }, m || {})); };
  const re = /(\*\*([^*]+)\*\*|__([^_]+)__|\*([^*\n]+)\*|_([^_\n]+)_|`([^`]+)`|\[([^\]]+)\]\(([^)\s]+)\))/g;
  let m; let last = 0;
  while ((m = re.exec(src))) {
    push(src.slice(last, m.index));
    if (m[2] || m[3]) push(m[2] || m[3], { bold: true });
    else if (m[4] || m[5]) push(m[4] || m[5], { italic: true });
    else if (m[6]) push(m[6], { code: true });
    else if (m[7]) push(m[7], { href: m[8] });
    last = m.index + m[0].length;
  }
  push(src.slice(last));
  return out;
}
function parseMarkdown(md) {
  const lines = String(md || '').replace(/\r/g, '').split('\n');
  const blocks = []; let para = []; let list = null;
  const flushPara = () => { if (para.length) { blocks.push({ type: 'paragraph', inlines: parseInline(para.join(' ')) }); para = []; } };
  const flushList = () => { if (list) { blocks.push(list); list = null; } };
  for (const raw of lines) {
    const t = raw.trim();
    if (!t) { flushPara(); flushList(); continue; }
    let m;
    if ((m = t.match(/^!\[([^\]]*)\]\(([^)\s]+)\)$/))) { flushPara(); flushList(); const pm = m[2].match(/^markimate:image:(\d+)$/); blocks.push({ type: 'image', alt: m[1], src: pm ? '' : m[2], idx: pm ? Number(pm[1]) : null }); continue; }
    if ((m = t.match(/^(#{1,6})\s+(.*)$/))) { flushPara(); flushList(); blocks.push({ type: 'heading', level: Math.min(Math.max(m[1].length, 2), 4), inlines: parseInline(m[2].replace(/\s#+$/, '')) }); continue; }
    if ((m = t.match(/^[-*+]\s+(.*)$/))) { flushPara(); if (!list || list.ordered) { flushList(); list = { type: 'list', ordered: false, items: [] }; } list.items.push(parseInline(m[1])); continue; }
    if ((m = t.match(/^\d+[.)]\s+(.*)$/))) { flushPara(); if (!list || !list.ordered) { flushList(); list = { type: 'list', ordered: true, items: [] }; } list.items.push(parseInline(m[1])); continue; }
    if ((m = t.match(/^>\s?(.*)$/))) { flushPara(); flushList(); blocks.push({ type: 'quote', inlines: parseInline(m[1]) }); continue; }
    if (/^(-{3,}|\*{3,})$/.test(t)) { flushPara(); flushList(); continue; }
    flushList(); para.push(t);
  }
  flushPara(); flushList();
  return blocks;
}
const escHtml = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
function inlinesToHtml(inl) {
  return inl.map(x => { let h = escHtml(x.text); if (x.code) h = '<code>' + h + '</code>'; if (x.bold) h = '<strong>' + h + '</strong>'; if (x.italic) h = '<em>' + h + '</em>'; if (x.href) h = '<a href="' + escHtml(x.href) + '" target="_blank" rel="noopener">' + h + '</a>'; return h; }).join('');
}
function markdownToHtml(md) {
  return parseMarkdown(md).map(b => {
    if (b.type === 'heading') return '<h' + b.level + '>' + inlinesToHtml(b.inlines) + '</h' + b.level + '>';
    if (b.type === 'image') return b.idx !== null ? '<img data-markimate-idx="' + b.idx + '" alt="' + escHtml(b.alt) + '">' : '<figure><img src="' + escHtml(b.src) + '" alt="' + escHtml(b.alt) + '"></figure>';
    if (b.type === 'quote') return '<blockquote><p>' + inlinesToHtml(b.inlines) + '</p></blockquote>';
    if (b.type === 'list') return (b.ordered ? '<ol>' : '<ul>') + b.items.map(it => '<li>' + inlinesToHtml(it) + '</li>').join('') + (b.ordered ? '</ol>' : '</ul>');
    return '<p>' + inlinesToHtml(b.inlines) + '</p>';
  }).join('\n');
}
// Ricos (Wix rich content)
function markdownToRicos(md) {
  let seq = 0; const nid = () => 'n' + (++seq).toString(36) + Date.now().toString(36).slice(-4);
  const textNode = x => { const dec = []; if (x.bold) dec.push({ type: 'BOLD', fontWeightValue: 700 }); if (x.italic) dec.push({ type: 'ITALIC', italicData: true }); if (x.href) dec.push({ type: 'LINK', linkData: { link: { url: x.href, target: 'BLANK' } } }); return { type: 'TEXT', id: '', nodes: [], textData: { text: x.text, decorations: dec } }; };
  const paragraph = inl => ({ type: 'PARAGRAPH', id: nid(), nodes: inl.map(textNode), paragraphData: {} });
  const nodes = [];
  for (const b of parseMarkdown(md)) {
    if (b.type === 'image') continue; // gambar belum didukung di Wix (lihat warnings)
    if (b.type === 'heading') nodes.push({ type: 'HEADING', id: nid(), nodes: b.inlines.map(textNode), headingData: { level: b.level } });
    else if (b.type === 'quote') nodes.push({ type: 'BLOCKQUOTE', id: nid(), nodes: [paragraph(b.inlines)], blockquoteData: {} });
    else if (b.type === 'list') nodes.push({ type: b.ordered ? 'ORDERED_LIST' : 'BULLETED_LIST', id: nid(), nodes: b.items.map(it => ({ type: 'LIST_ITEM', id: nid(), nodes: [paragraph(it)] })), [b.ordered ? 'orderedListData' : 'bulletedListData']: { indentation: 0 } });
    else nodes.push(paragraph(b.inlines));
  }
  return { nodes, metadata: { version: 1 } };
}
// Portable Text (Sanity block content)
function markdownToPortableText(md) {
  let seq = 0; const key = () => 'k' + (++seq).toString(36) + Math.random().toString(36).slice(2, 8);
  const block = (inl, extra) => {
    const markDefs = [];
    const children = (inl.length ? inl : [{ text: '' }]).map(x => {
      const marks = [];
      if (x.bold) marks.push('strong'); if (x.italic) marks.push('em'); if (x.code) marks.push('code');
      if (x.href) { const k = key(); markDefs.push({ _key: k, _type: 'link', href: x.href }); marks.push(k); }
      return { _type: 'span', _key: key(), text: x.text, marks };
    });
    return Object.assign({ _type: 'block', _key: key(), style: 'normal', markDefs, children }, extra || {});
  };
  const out = [];
  for (const b of parseMarkdown(md)) {
    if (b.type === 'image') { if (b.idx !== null) out.push({ _type: 'image', _key: key(), _markimateIdx: b.idx, alt: b.alt }); continue; }
    if (b.type === 'heading') out.push(block(b.inlines, { style: 'h' + b.level }));
    else if (b.type === 'quote') out.push(block(b.inlines, { style: 'blockquote' }));
    else if (b.type === 'list') for (const it of b.items) out.push(block(it, { listItem: b.ordered ? 'number' : 'bullet', level: 1 }));
    else out.push(block(b.inlines));
  }
  return out;
}


const headers = { Authorization: String(X.apiKey || ''), 'wix-site-id': String(X.siteId || ''), 'Content-Type': 'application/json' };
let draftPost = null;
if (A.title) {
  draftPost = {
    title: String(A.title).slice(0, 200),
    excerpt: String(A.excerpt || '').slice(0, 500),
    richContent: markdownToRicos(A.bodyMarkdown || A.body || ''),
    seoSlug: String(A.slug || '').trim() || undefined,
  };
}
if (!draftPost && !postId) throw new Error('Tidak ada artikel maupun postId untuk diproses.');

return [{ json: {
  cmsType: 'wix', action, postId, siteId: String(X.siteId || ''), memberIdInput: String(X.memberId || ''),
  headers, draftPost,
  keyword: A.primaryKeyword || '', title: A.title || '', requestId: IN.requestId || '',
} }];

// Adapter Wix Blog — tentukan memberId (penulis) & susun request berikutnya
const P = $('Siapkan Wix').first().json;
const posts = $('Wix: Cek Posts').first().json || {};
const members = $input.first().json || {};
const bodyOf = r => { if (!r) return {}; if (r.body && typeof r.body === 'object') return r.body; if (typeof r.body === 'string') { try { return JSON.parse(r.body); } catch (e) { return {}; } } return r; };
const pb = bodyOf(posts), mb = bodyOf(members);
const pStatus = Number(posts.statusCode || 0), mStatus = Number(members.statusCode || 0);

if (pStatus === 401 || pStatus === 403) {
  return [{ json: { status: 'error', cmsType: 'wix', action: P.action, httpStatus: pStatus, message: 'Wix menolak API key / Site ID (' + pStatus + '). Pastikan API key dibuat di Wix Account > API Keys dengan izin Blog & Members, dan Site ID benar.', requestId: P.requestId } }];
}
if (pStatus >= 400) {
  return [{ json: { status: 'error', cmsType: 'wix', action: P.action, httpStatus: pStatus, message: 'Wix Blog API error ' + pStatus + ': ' + (pb.message || JSON.stringify(pb).slice(0, 200)), requestId: P.requestId } }];
}

let memberId = P.memberIdInput || '';
if (!memberId && Array.isArray(pb.posts) && pb.posts[0] && pb.posts[0].memberId) memberId = pb.posts[0].memberId;
if (!memberId && Array.isArray(mb.members) && mb.members[0] && mb.members[0].id) memberId = mb.members[0].id;
if (!memberId && !P.postId) {
  return [{ json: { status: 'error', cmsType: 'wix', action: P.action, httpStatus: mStatus, message: 'Tidak menemukan member/penulis di situs Wix (Blog belum punya post dan Members API tidak bisa diakses). Buat satu post dulu di Wix Blog atau beri izin "Members" pada API key.', requestId: P.requestId } }];
}

const draftPost = P.draftPost ? Object.assign({}, P.draftPost, { memberId }) : null;
return [{ json: {
  status: 'prep', cmsType: 'wix', action: P.action, postId: P.postId, siteId: P.siteId, headers: P.headers, memberId,
  createBody: draftPost ? { draftPost, publish: P.action === 'publish', fieldsets: ['URL'] } : null,
  publishUrl: P.postId ? 'https://www.wixapis.com/blog/v3/draft-posts/' + P.postId + '/publish' : '',
  title: P.title, requestId: P.requestId,
} }];

// Adapter Wix Blog — rapikan hasil jadi format standar Supermat
const first = $input.first().json || {};
if (first.status === 'error') return [{ json: first }]; // error dari tahap sebelumnya diteruskan

const M = $('Tentukan Member').first().json;
const bodyOf = r => { if (!r) return {}; if (r.body && typeof r.body === 'object') return r.body; if (typeof r.body === 'string') { try { return JSON.parse(r.body); } catch (e) { return { raw: r.body.slice(0, 300) }; } } return r; };
const get = n => { try { return $(n).first().json; } catch (e) { return null; } };

const created = get('Wix: Buat Draft');
const published = get('Wix: Publish Draft');
const urlRes = get('Wix: Ambil URL');

let httpStatus = 0, b = {};
if (created) { httpStatus = Number(created.statusCode || 0); b = bodyOf(created); }
else if (published) { httpStatus = Number(published.statusCode || 0); b = bodyOf(published); }

if (httpStatus >= 400 || (!created && !published)) {
  const msg = b.message || (b.details && JSON.stringify(b.details).slice(0, 300)) || b.raw || ('HTTP ' + httpStatus);
  return [{ json: { status: 'error', cmsType: 'wix', action: M.action, httpStatus, message: 'Wix Blog API gagal: ' + msg, requestId: M.requestId } }];
}

const draftId = (b.draftPost && b.draftPost.id) || b.postId || M.postId || '';
const postId = b.postId || (b.post && b.post.id) || draftId;
const ub = bodyOf(urlRes);
const url = (ub.post && ub.post.url) || (b.post && b.post.url) || (b.draftPost && b.draftPost.url) || null;
const publicUrl = url && url.base ? String(url.base).replace(/\/+$/, '') + String(url.path || '') : '';
const isPublished = M.action === 'publish' && httpStatus < 400;

return [{ json: {
  status: 'ok', cmsType: 'wix', action: M.action,
  postId: String(draftId), postStatus: isPublished ? 'publish' : 'draft',
  draftEditUrl: 'https://manage.wix.com/dashboard/' + M.siteId + '/blog/' + draftId + '/edit',
  publicUrl: isPublished ? publicUrl : '',
  title: (b.draftPost && b.draftPost.title) || M.title,
  message: isPublished ? 'Artikel terbit di Wix Blog.' : 'Draf tersimpan di Wix Blog.',
  requestId: M.requestId,
} }];
